#include "fractal/connection.h"
fractal_connection_transition fractal_connection_reduce(fractal_connection_state s,fractal_connection_event e){fractal_connection_transition t={false,s,s,FRACTAL_CONN_REJECT_INVALID_TRANSITION};switch(e){case FRACTAL_EVENT_APP_START:if(s==FRACTAL_CONN_UNINITIALIZED){t=(fractal_connection_transition){true,s,FRACTAL_CONN_DISCONNECTED,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_DISCOVERY_STARTED:if(s==FRACTAL_CONN_DISCONNECTED){t=(fractal_connection_transition){true,s,FRACTAL_CONN_DISCOVERING,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_KNOWN_SERVICE_AVAILABLE:if(s==FRACTAL_CONN_DISCONNECTED||s==FRACTAL_CONN_DISCOVERING){t=(fractal_connection_transition){true,s,FRACTAL_CONN_CONNECTING,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_TRANSPORT_ESTABLISHED:if(s==FRACTAL_CONN_CONNECTING){t=(fractal_connection_transition){true,s,FRACTAL_CONN_NEGOTIATING,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_COMPATIBILITY_ACCEPTED:if(s==FRACTAL_CONN_NEGOTIATING){t=(fractal_connection_transition){true,s,FRACTAL_CONN_AUTHENTICATING,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_AUTHENTICATION_ACCEPTED:if(s==FRACTAL_CONN_AUTHENTICATING){t=(fractal_connection_transition){true,s,FRACTAL_CONN_REACQUIRING,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_REACQUIRE_SYNCHRONIZED:if(s==FRACTAL_CONN_REACQUIRING){t=(fractal_connection_transition){true,s,FRACTAL_CONN_SYNCHRONIZED,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_NETWORK_LOST:if(s!=FRACTAL_CONN_UNINITIALIZED){t=(fractal_connection_transition){true,s,FRACTAL_CONN_DISCONNECTED,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_APP_BACKGROUND:t=(fractal_connection_transition){true,s,FRACTAL_CONN_SUSPENDED,FRACTAL_CONN_REJECT_NONE};break;case FRACTAL_EVENT_APP_FOREGROUND:if(s==FRACTAL_CONN_SUSPENDED){t=(fractal_connection_transition){true,s,FRACTAL_CONN_DISCONNECTED,FRACTAL_CONN_REJECT_NONE};}break;case FRACTAL_EVENT_COMPATIBILITY_REJECTED:t=(fractal_connection_transition){true,s,FRACTAL_CONN_INCOMPATIBLE,FRACTAL_CONN_REJECT_INCOMPATIBLE};break;case FRACTAL_EVENT_AUTHENTICATION_REVOKED:t=(fractal_connection_transition){true,s,FRACTAL_CONN_REVOKED,FRACTAL_CONN_REJECT_REVOKED};break;case FRACTAL_EVENT_SERVICE_RESTARTED:t=(fractal_connection_transition){true,s,FRACTAL_CONN_DISCONNECTED,FRACTAL_CONN_REJECT_NONE};break;case FRACTAL_EVENT_SERVICE_IDENTITY_CHANGED:t=(fractal_connection_transition){true,s,FRACTAL_CONN_REVOKED,FRACTAL_CONN_REJECT_IDENTITY_ROTATION};break;case FRACTAL_EVENT_FAILURE:t=(fractal_connection_transition){true,s,FRACTAL_CONN_FAILED,FRACTAL_CONN_REJECT_NONE};break;}return t;}
